function table(rows,heads){if(!rows.length)return "<p>No records yet.</p>";return "<div class=\"table-wrap\"><table><thead><tr>"+heads.map(h=>`<th>${h}</th>`).join("")+"</tr></thead><tbody>"+rows.slice().reverse().map(r=>"<tr>"+r.map(c=>`<td>${c}</td>`).join("")+"</tr>").join("")+"</tbody></table></div>"}
