async function saveSales(){let total=0,qty={};foods.forEach((f,i)=>{let q=parseInt(document.getElementById("q"+i).value)||0;qty[f]=q;total+=q*(data.prices[f]||0)});if(!total)return alert("Enter at least one quantity and make sure prices are set.");data.sales.push({date:today(),qty,total});await save();alert("Today's sales saved. Total: "+money(total));}
