function billCalc(){
  let subtotal=0,totalDiscount=0,taxable=0,totalGST=0,grandTotal=0,items=[];
  document.querySelectorAll(".billq").forEach(x=>{
    const i=+x.dataset.i,q=Math.max(0,+x.value||0),price=Number(data.prices[foods[i]])||DEFAULT_PRICES[foods[i]]||0;
    const discountPct=Math.max(0,Math.min(100,+document.querySelector(`.billdisc[data-i=\"${i}\"]`)?.value||0));
    const gstPct=Math.max(0,+document.querySelector(`.billgst[data-i=\"${i}\"]`)?.value||0);
    const amount=q*price,discountAmount=amount*discountPct/100,taxableAmount=amount-discountAmount,gstAmount=taxableAmount*gstPct/100,total=taxableAmount+gstAmount;
    if(q){items.push({name:foods[i],qty:q,price,total,amount,discountPct,discountAmount,taxableAmount,gstPct,gstAmount});}
    subtotal+=amount;totalDiscount+=discountAmount;taxable+=taxableAmount;totalGST+=gstAmount;grandTotal+=total;
  });
  return {subtotal,totalDiscount,taxable,totalGST,grandTotal,items,total:grandTotal,net:subtotal,gst:totalGST,gstRate:0};
}
function updateBillTotal(){
  const c=billCalc();
  document.querySelectorAll(".billq").forEach(x=>{
    const i=+x.dataset.i,q=Math.max(0,+x.value||0),price=Number(data.prices[foods[i]])||DEFAULT_PRICES[foods[i]]||0;
    const discountPct=Math.max(0,Math.min(100,+document.querySelector(`.billdisc[data-i=\"${i}\"]`)?.value||0));
    const gstPct=Math.max(0,+document.querySelector(`.billgst[data-i=\"${i}\"]`)?.value||0);
    const amount=q*price,discountAmount=amount*discountPct/100,taxableAmount=amount-discountAmount,gstAmount=taxableAmount*gstPct/100,total=taxableAmount+gstAmount;
    document.getElementById("discount"+i).textContent=money(discountAmount);document.getElementById("gst"+i).textContent=money(gstAmount);document.getElementById("line"+i).textContent=money(total);
  });
  document.getElementById("billSubtotal").textContent=money(c.subtotal);document.getElementById("billDiscount").textContent=money(c.totalDiscount);document.getElementById("billTaxable").textContent=money(c.taxable);document.getElementById("billGST").textContent=money(c.totalGST);document.getElementById("billGrand").textContent=money(c.grandTotal);
}
