function report(){let a=document.getElementById("fromDate").value,b=document.getElementById("toDate").value;if(!a||!b)return alert("Select both dates.");if(a>b)return alert("From date cannot be after To date.");let inv=data.invoices.filter(x=>x.date>=a&&x.date<=b&&(x.status||"issued")==="quotation"),ee=data.expenses.filter(x=>x.date>=a&&x.date<=b&&x.category!=="Investment");let quotationTotal=inv.reduce((z,x)=>z+Number(x.total||0),0),e=ee.reduce((z,x)=>z+Number(x.amount||0),0),netAfter=quotationTotal-e;document.getElementById("rCustomers").textContent=inv.length;document.getElementById("rInvoices").textContent=inv.length;document.getElementById("rNet").textContent=money(quotationTotal);document.getElementById("rGST").textContent=money(inv.reduce((z,x)=>z+Number(x.gst||0),0));document.getElementById("rSales").textContent=money(quotationTotal);document.getElementById("rExp").textContent=money(e);document.getElementById("rProfit").textContent=money(netAfter);let days=[...new Set([...inv.map(x=>x.date),...ee.map(x=>x.date)])].sort();let rows=days.map(d=>{let di=inv.filter(x=>x.date===d),de=ee.filter(x=>x.date===d),qt=di.reduce((z,x)=>z+Number(x.total||0),0),ex=de.reduce((z,x)=>z+Number(x.amount||0),0);return [d,di.length,di.length,money(qt),money(ex),money(qt-ex)]});document.getElementById("reportTable").innerHTML=table(rows,["Date","Customer Visits","Quotations","Quotation Value","Expenses","Balance After Expenses"]);document.getElementById("reportInvoices").innerHTML=table(inv.map(x=>[x.invoiceNo,x.date,x.customer,x.phone||"—",money(x.total)]),["Quotation","Date","Customer","Phone","Total"])}
