async function dbInsertExpense(expense){if(!appCurrentUser||!window.sb)throw new Error("Not connected to cloud");const {error}=await sb.from("expenses").insert({user_id:appCurrentUser.id,expense_date:expense.date,category:expense.category,amount:expense.amount,notes:expense.note||null});if(error)throw error}
async function dbSaveInvoice(inv){if(!appCurrentUser||!window.sb)throw new Error("Not connected to cloud");let customerId=null;const {data:found,error:findErr}=await sb.from("customers").select("id").eq("user_id",appCurrentUser.id).ilike("name",inv.customer).limit(1).maybeSingle();if(findErr)throw findErr;if(found)customerId=found.id;else{const ins=await sb.from("customers").insert({user_id:appCurrentUser.id,name:inv.customer,phone:inv.phone||null}).select("id").single();if(ins.error)throw ins.error;customerId=ins.data.id}
const invoiceRow={id:inv.id,user_id:appCurrentUser.id,customer_id:customerId,invoice_number:inv.invoiceNo,invoice_date:inv.date,gst_rate:inv.gstRate,subtotal:inv.net,gst_amount:inv.gst,total_amount:inv.total,status:inv.status||"issued"};let ir=null;for(let attempt=0;attempt<3;attempt++){ir=await sb.from("invoices").insert(invoiceRow).select("id").single();if(!ir.error)break;if(ir.error.code==="23505"&&ir.error.message.includes("invoices_user_invoice_number_uq")){inv.invoiceNo=nextInvoiceNo();invoiceRow.invoice_number=inv.invoiceNo;await new Promise(r=>setTimeout(r,50));continue;}throw ir.error;}if(ir?.error)throw ir.error;const rows=inv.items.map(i=>({invoice_id:ir.data.id,user_id:appCurrentUser.id,item_name:i.name,unit_price:i.price,quantity:i.qty,line_total:i.total}));const items=await sb.from("invoice_items").insert(rows);if(items.error)throw items.error;if((inv.status||"issued")!=="quotation"){const pay=await sb.from("payments").insert({user_id:appCurrentUser.id,invoice_id:ir.data.id,payment_date:inv.date,amount:inv.total,method:"Cash",status:"paid"});if(pay.error)throw pay.error}}
function renderHotelBranding(){
  // Fixed hotel branding is part of this webpage and is NOT written to localStorage or Supabase.
  const nameEl=document.getElementById("hotelNameDisplay");
  if(nameEl) nameEl.textContent="SAMUDHRA FOODS";
  const img=document.getElementById("hotelLogo");
  if(img){img.src="data:image/png;base64,";img.style.display="block";}
  const fixedFields={setHotelName:"SAMUDHRA FOODS",setPhone:"+91 81222 17228",setInstagram:"@SAMUDHRAFOODS"};
  Object.entries(fixedFields).forEach(([id,val])=>{const el=document.getElementById(id);if(el){el.value=val;el.readOnly=true;}});
}
async function saveHotelSettings(){
  try{
    // Fixed client-facing identity details (name/phone/Instagram) are NOT stored in cloud/local data.
    const logoUrl=document.getElementById("setLogo").value.trim();
    data.settings={...data.settings,
      email:document.getElementById("setEmail").value.trim(),
      gstNumber:document.getElementById("setGSTNo").value.trim(),
      fssaiNumber:document.getElementById("setFSSAI").value.trim(),
      logoUrl,
      address:document.getElementById("setAddress").value.trim(),
      contactDetails:document.getElementById("setContact").value.trim()
    };
    await saveSettingsOnly();
    localStorage.setItem("hotelData",JSON.stringify(data));
    renderHotelBranding();
    document.getElementById("settingsMsg").textContent="Settings saved. Fixed hotel name, phone and Instagram are built into this webpage and are not stored in hotel data.";
    alert("Settings saved.");
  }catch(e){document.getElementById("settingsMsg").textContent="Could not save settings: "+e.message}
}
async function saveSettingsOnly(){if(!appCurrentUser||!window.sb)return;const settings={prices:data.prices,email:data.settings.email||"",gstNumber:data.settings.gstNumber||"",fssaiNumber:data.settings.fssaiNumber||"",logoUrl:data.settings.logoUrl||"",address:data.settings.address||"",contactDetails:data.settings.contactDetails||"",quotationMeta:data.settings.quotationMeta||{}};const r=await sb.from("hotel_settings").upsert({user_id:appCurrentUser.id,settings},{onConflict:"user_id"});if(r.error)throw r.error}
async function loadNormalized(){
  if(!appCurrentUser||!window.sb)return;
  const uid=appCurrentUser.id;
  // Cloud is the source of truth. Do not restore or mix localStorage data during login;
  // localStorage is browser-wide and must never be used to populate another hotel account.
  const withTimeout=(promise,label,ms=12000)=>Promise.race([promise,new Promise((_,reject)=>setTimeout(()=>reject(new Error(label+" timed out. Please try again.")),ms))]);
  const [cr,ir,er,sr]=await withTimeout(Promise.all([
    sb.from("customers").select("*").eq("user_id",uid).order("created_at",{ascending:true}),
    sb.from("invoices").select("*").eq("user_id",uid).order("invoice_date",{ascending:true}).order("created_at",{ascending:true}),
    sb.from("expenses").select("*").eq("user_id",uid).order("expense_date",{ascending:true}).order("created_at",{ascending:true}),
    sb.from("hotel_settings").select("settings").eq("user_id",uid).maybeSingle()
  ]),"Cloud data loading",12000);
  for(const r of [cr,ir,er,sr]) if(r.error) throw r.error;

  const invoiceRows=ir.data||[];

  const invoiceIds=invoiceRows.map(x=>x.id);
  let itemRows=[];
  if(invoiceIds.length){
    const items=await withTimeout(sb.from("invoice_items").select("*").eq("user_id",uid).in("invoice_id",invoiceIds).order("created_at",{ascending:true}),"Quotation items loading",12000);
    if(items.error) throw items.error;
    itemRows=items.data||[];
  }
  const customerById=new Map((cr.data||[]).map(c=>[c.id,c]));
  data.customers=(cr.data||[]).map(c=>({id:c.id,name:c.name,phone:c.phone||"",invoices:0,lastInvoice:"",totalSpent:0}));
  data.invoices=invoiceRows.map(x=>{
    const c=customerById.get(x.customer_id);
    return {id:x.id,invoiceNo:x.invoice_number,date:x.invoice_date,customer:c?.name||"",phone:c?.phone||"",items:itemRows.filter(i=>i.invoice_id===x.id).map(i=>({name:i.item_name,qty:Number(i.quantity),price:Number(i.unit_price),total:Number(i.line_total)})),net:Number(x.subtotal),gst:Number(x.gst_amount),gstRate:Number(x.gst_rate),total:Number(x.total_amount),status:x.status||"issued"};
  });
  data.expenses=(er.data||[]).map(e=>({id:e.id,date:e.expense_date,category:e.category,amount:Number(e.amount),note:e.notes||""}));
  if(sr.data?.settings){
    data.settings={...data.settings,...sr.data.settings};
    delete data.settings.hotelName; delete data.settings.phone; delete data.settings.instagram;
    if(sr.data.settings.prices) data.prices=sr.data.settings.prices;
  }
  const quotationMeta=data.settings.quotationMeta||{};
  data.invoices.forEach(inv=>{const m=quotationMeta[inv.invoiceNo];if(m){inv.paymentTerms=m.paymentTerms||"As mutually agreed";inv.quotationValidity=m.quotationValidity||"15 days from quotation date";inv.remarks=m.remarks||"";inv.subtotal=Number(m.subtotal??inv.net??0);inv.totalDiscount=Number(m.totalDiscount??0);inv.taxableAmount=Number(m.taxableAmount??(inv.subtotal-inv.totalDiscount));inv.totalGST=Number(m.totalGST??inv.gst??0);inv.total=Number(m.grandTotal??inv.total??0);if(Array.isArray(m.items)&&m.items.length){const byName=new Map(m.items.map(i=>[i.name,i]));inv.items=inv.items.map(i=>({...i,...(byName.get(i.name)||{})}));}}});
  renderHotelBranding();
  data.customers.forEach(c=>{
    const list=data.invoices.filter(i=>(i.status||"issued")==="quotation" && i.customer===c.name && (c.phone?i.phone===c.phone:true));
    c.invoices=list.length; c.totalSpent=list.reduce((a,i)=>a+i.total,0); c.lastInvoice=list.length?list[list.length-1].date:"";
  });
  localStorage.setItem("hotelData",JSON.stringify(data));
}

// Local cache repair is intentionally disabled during login to preserve strict per-account cloud isolation.
async function migrateLegacyIfNeeded(){
  if(!appCurrentUser||!window.sb)return;
  const {count,error}=await Promise.race([
    sb.from("invoices").select("id",{count:"exact",head:true}).eq("user_id",appCurrentUser.id),
    new Promise((_,reject)=>setTimeout(()=>reject(new Error("Cloud connection timed out while checking your hotel data.")),12000))
  ]);
  if(error)throw error;
  if((count||0)>0)return;
  const legacy=await sb.from("hotel_data").select("data").eq("user_id",appCurrentUser.id).maybeSingle();
  if(legacy.error)throw legacy.error;
  if(!legacy.data?.data)return;
  const old={...EMPTY_DATA,...legacy.data.data};
  for(const f of old.expenses||[]) await dbInsertExpense(f);
  for(const inv of old.invoices||[]) await dbSaveInvoice(inv);
  if(old.prices){data.prices=old.prices;}
  await saveSettingsOnly();
}
async function cloudLoad(){if(!window.sb||!appCurrentUser)throw new Error("Authenticated user session is missing.");await migrateLegacyIfNeeded();await loadNormalized();document.getElementById("billDate").value=today();render();setTodayReport()}
function getCloudConfig(){const url=(window.SUPABASE_URL||"").trim().replace(/\/$/,"");const key=(window.SUPABASE_ANON_KEY||"").trim();if(!url||!key)return null;return {url,key}}
function showSetup(){document.getElementById("authMsg").textContent="Login service is not configured. Please contact the hotel administrator."}
async function login(){
  const msg=document.getElementById("authMsg");
  const email=document.getElementById("authEmail").value.trim();
  const password=document.getElementById("authPassword").value;
  if(!email||!password){msg.textContent="Enter your email and password.";return;}
  msg.textContent="Connecting to secure login…";
  const loginBtn=document.querySelector('#auth button[onclick="login()"]');
  if(loginBtn)loginBtn.disabled=true;
  try{
    if(!window.sb){const ok=await initCloud();if(!ok)return;}
    const result=await sb.auth.signInWithPassword({email,password});
    if(result.error){
      const e=result.error;
      const m=(e.message||"").toLowerCase();
      if(m.includes("email not confirmed")) msg.textContent="Email not confirmed. Please open the Supabase confirmation email, confirm the account, then sign in again.";
      else if(m.includes("invalid login credentials")) msg.textContent="Email or password is incorrect. If you have not created an account yet, use Create Hotel Account.";
      else msg.textContent="Sign-in failed: "+e.message;
      return;
    }
    if(!result.data||!result.data.user){msg.textContent="Sign-in completed, but no user session was returned. Please try again.";return;}
    msg.textContent="Signed in. Loading your hotel data…";
    try{
      await startSession(result.data.user);
    }catch(e){
      console.error("Cloud data error after sign-in",e);
      msg.textContent="Login successful, but hotel data could not be loaded: "+(e?.message||e);
    }
  }catch(e){
    console.error("Sign-in error",e);
    msg.textContent="Sign-in error: "+(e?.message||e);
  }finally{
    if(loginBtn)loginBtn.disabled=false;
  }
}
async function signup(){
  const msg=document.getElementById("authMsg");
  const email=document.getElementById("authEmail").value.trim();
  const password=document.getElementById("authPassword").value;
  if(!email){msg.textContent="Enter an email address.";return;}
  if(password.length<6){msg.textContent="Password must be at least 6 characters.";return;}
  msg.textContent="Creating hotel account…";
  try{
    if(!window.sb){const ok=await initCloud();if(!ok)return;}
    const result=await sb.auth.signUp({email,password});
    if(result.error){msg.textContent="Account creation failed: "+result.error.message;return;}
    if(result.data&&result.data.session){await startSession(result.data.user);return;}
    msg.textContent="Account created. Check your email to confirm the account, then sign in.";
  }catch(e){console.error("Signup error",e);msg.textContent="Account creation error: "+(e?.message||e); }
}
async function forgotPassword(){
  const email=document.getElementById("authEmail").value.trim();
  const msg=document.getElementById("authMsg");
  if(!email){msg.textContent="Enter your account email first.";return;}
  try{
    if(!window.sb){const ok=await initCloud();if(!ok)return;}
    msg.textContent="Sending password reset email…";
    const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});
    if(error) msg.textContent="Password reset failed: "+error.message;
    else msg.textContent="Password reset email sent. Check your inbox.";
  }catch(e){console.error("Password reset error",e);msg.textContent="Password reset error: "+(e?.message||e);}
}
async function logout(){if(window.sb)await sb.auth.signOut();appCurrentUser=null;document.getElementById("auth").style.display="flex";document.querySelector("main").style.display="none";document.querySelector("header").style.display="none"}
async function startSession(user){appCurrentUser=user;document.getElementById("auth").style.display="none";document.querySelector("main").style.display="block";document.querySelector("header").style.display="block";document.getElementById("signedInAs").textContent="Signed in: "+user.email;await cloudLoad()}
async function initCloud(){if(window.sb)return true;if(!window.supabase){document.getElementById("authMsg").textContent="Unable to load the login service. Check your internet connection.";return false}const c=getCloudConfig();if(!c){document.getElementById("authMsg").textContent="Login service configuration is missing.";return false}try{window.sb=supabase.createClient(c.url,c.key);return true}catch(e){console.error(e);document.getElementById("authMsg").textContent="Login service error: "+e.message;return false}}
async function init(){const ok=await initCloud();if(!ok)return;const {data,error}=await sb.auth.getSession();if(error){document.getElementById("authMsg").textContent="Login service error: "+error.message;return}if(data.session)await startSession(data.session.user)}
renderHotelBranding();init();
